let lifeStore='cafe',pendingLifeItem=null,assetTab='all';
function migrateLife(s){if(!s)return;const l=s.life&&typeof s.life==='object'&&!Array.isArray(s.life)?s.life:{};s.life={hunger:Number.isFinite(l.hunger)?Math.max(0,Math.min(100,l.hunger)):75,energy:Number.isFinite(l.energy)?Math.max(0,Math.min(100,l.energy)):80,joy:Number.isFinite(l.joy)?Math.max(0,Math.min(100,l.joy)):60,spent:Number.isSafeInteger(l.spent)&&l.spent>=0?l.spent:0,day:Number.isSafeInteger(l.day)&&l.day>0?l.day:1,inventory:{},equippedCar:null,equippedHome:null,equippedLuxury:null,history:Array.isArray(l.history)?l.history.slice(0,80):[]};for(const it of ITEMS){if(['car','house','luxury'].includes(it.kind)&&l.inventory?.[it.id]===1)s.life.inventory[it.id]=1;}for(const [key,kind]of [['equippedCar','car'],['equippedHome','house'],['equippedLuxury','luxury']])if(ITEMS.some(it=>it.id===l[key]&&it.kind===kind)&&s.life.inventory[l[key]])s.life[key]=l[key];}
function assetValue(s){return ITEMS.filter(it=>s?.life?.inventory?.[it.id]).reduce((sum,it)=>sum+it.price,0)}
function lifeNet(s){return s.balance+(s.savings||0)+assetValue(s)-s.debt}
function itemArt(it){const c=it.color;let inner='';if(it.kind==='car')inner='<ellipse cx="150" cy="119" rx="117" ry="13" fill="#455444" opacity=".12"/><path d="M33 89 L44 71 L85 65 L111 41 L178 41 L205 66 L244 78 L259 97 L254 112 L31 112Z" fill="'+c+'"/><path d="M97 65 L118 47 L172 47 L190 65Z" fill="#e0e7de"/><path d="M140 47 L140 65" stroke="'+c+'" stroke-width="5"/><path d="M43 82 L69 81 L64 88 L38 89 M226 84 L246 89" stroke="#fff0b5" stroke-width="5"/><circle cx="79" cy="110" r="18" fill="#384137"/><circle cx="79" cy="110" r="9" fill="#bdc9b5"/><circle cx="215" cy="110" r="18" fill="#384137"/><circle cx="215" cy="110" r="9" fill="#bdc9b5"/>';
else if(it.kind==='house')inner='<ellipse cx="150" cy="132" rx="110" ry="10" fill="#455444" opacity=".1"/><path d="M59 61 L149 18 L240 61Z" fill="'+c+'"/><path d="M72 59 L228 59 L228 128 L72 128Z" fill="#f1e3c6"/><path d="M62 60 L238 60" stroke="#514f44" stroke-width="6"/><rect x="94" y="74" width="31" height="29" fill="#94b7b2"/><rect x="174" y="74" width="31" height="29" fill="#94b7b2"/><rect x="139" y="83" width="25" height="45" fill="'+c+'"/><path d="M108 74 L108 103 M94 87 L125 87 M189 74 L189 103 M174 87 L205 87" stroke="#fff4d8" stroke-width="3"/><path d="M123 130 L178 130 L184 138 L116 138Z" fill="#c9bc9c"/><rect x="55" y="112" width="20" height="21" rx="3" fill="#b07856"/><circle cx="64" cy="105" r="18" fill="#6f9662"/>';
else if(it.kind==='food')inner='<ellipse cx="150" cy="111" rx="83" ry="25" fill="#e5dcc7"/><path d="M76 81 Q87 135 150 137 Q214 134 224 81Z" fill="'+c+'"/><ellipse cx="150" cy="80" rx="75" ry="27" fill="#fcf0d4"/><ellipse cx="150" cy="79" rx="60" ry="19" fill="#d2b372"/><path d="M105 78 Q127 58 147 80 Q170 57 198 79 Q171 100 149 84 Q127 100 105 78" fill="#8f5b3d"/><circle cx="174" cy="71" r="10" fill="#c86746"/><path d="M113 71 L120 63 M135 78 L144 66 M187 85 L198 75" stroke="#789258" stroke-width="6" stroke-linecap="round"/><path d="M123 39 Q112 27 123 16 M151 39 Q140 27 151 16 M179 39 Q168 27 179 16" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" opacity=".7"/>';
else if(it.kind==='stay')inner='<path d="M57 59 L57 123 M244 67 L244 123" stroke="#806b51" stroke-width="10" stroke-linecap="round"/><path d="M61 61 L61 39 Q151 19 240 39 L240 76Z" fill="'+c+'"/><path d="M66 62 L236 62 L252 106 L49 106Z" fill="#f9eddb"/><path d="M73 65 L130 65 L125 81 L68 81Z M163 65 L220 65 L226 81 L169 81Z" fill="#fffdf4"/><path d="M58 84 L242 84 L252 106 L49 106Z" fill="'+c+'" opacity=".6"/><path d="M49 109 L251 109" stroke="#806b51" stroke-width="7"/><circle cx="266" cy="34" r="16" fill="#e9ce85"/>';
else if(it.id==='watch')inner='<rect x="131" y="13" width="38" height="122" rx="9" fill="'+c+'"/><circle cx="150" cy="74" r="36" fill="#d7c495"/><circle cx="150" cy="74" r="29" fill="#315560"/><path d="M150 54 L150 75 L167 82" stroke="#eadcb3" stroke-width="3" fill="none"/><circle cx="150" cy="74" r="3" fill="#eadcb3"/>';
else if(it.id==='necklace')inner='<path d="M98 22 Q84 91 150 111 Q217 91 202 22" fill="none" stroke="#cfbf88" stroke-width="4"/><path d="M150 93 L167 109 L150 133 L134 109Z" fill="#fcf6ff" stroke="'+c+'" stroke-width="3"/><path d="M150 98 L150 125 M140 108 L161 108" stroke="#c9c1d8" stroke-width="2"/><path d="M195 75 L199 66 L203 75 L211 79 L203 83 L199 92 L195 83 L186 79Z" fill="#fff"/>';
else inner='<path d="M94 62 L206 62 L219 126 L81 126Z" fill="'+c+'"/><path d="M118 65 L118 42 Q151 6 182 42 L182 65" fill="none" stroke="'+c+'" stroke-width="10"/><path d="M93 76 L206 76 M150 79 L150 126" fill="none" stroke="#f4dfb6" stroke-width="2" opacity=".5"/><rect x="139" y="75" width="23" height="16" rx="3" fill="#d9c48a"/>';
return '<svg viewBox="0 0 300 150" role="img" aria-label="'+esc(it.name)+'">'+inner+'</svg>';}
function effectText(it){if(it.kind==='food')return '飽足 +'+it.hunger+' · 精神 +'+it.energy+' · 心情 +'+it.joy;if(it.kind==='stay')return '前進一天 · 精神恢復 100 · 心情 +'+it.joy;if(it.kind==='car')return '可在小鎮駕駛 · 車速 '+it.speed;if(it.kind==='house')return '設為住所 · 回家免費休息';return '可配戴在角色身上 · 心情 +'+it.joy;}
function productCard(it,ownedView=false){const own=!!state?.life?.inventory[it.id],equipped=own&&[state.life.equippedCar,state.life.equippedHome,state.life.equippedLuxury].includes(it.id);return '<article class="product-card"><div class="product-art" style="background:'+it.color+'20">'+itemArt(it)+(own?'<span class="product-owned">'+(equipped?'使用中':'已收藏')+'</span>':'')+'</div><div class="product-content"><span class="product-category">'+{food:'HARBOUR KITCHEN',stay:'A GOOD NIGHT',car:'YOUR OWN WHEELS',house:'HOME SWEET HOME',luxury:'PERSONAL COLLECTION'}[it.kind]+'</span><h3>'+it.name+'</h3><p class="product-desc">'+it.desc+'</p><div class="product-effects">'+effectText(it)+'</div><div class="product-price">NT$ '+money(it.price)+'</div>'+(own?'<button class="'+(equipped?'chip':'secondary')+'" data-equip="'+it.id+'" '+(equipped?'disabled':'')+'>'+(equipped?'目前'+{car:'駕駛車款',house:'居住地',luxury:'配戴中'}[it.kind]:{car:'換開這一台',house:'搬到這裡',luxury:'配戴這件收藏'}[it.kind])+'</button>':'<button class="primary" data-life-buy="'+it.id+'">'+(it.kind==='food'?'點這一道':it.kind==='stay'?'今晚住這裡':'買下這'+(it.kind==='car'?'台車':it.kind==='house'?'個家':'件收藏'))+'</button>')+'</div></article>';}
function renderLifeStore(id){lifeStore=id;const st=LIFE_STORES[id];$('lifeShopTag').textContent=st.tag;$('lifeShopName').textContent=st.name;$('lifeShopQuote').textContent=st.staff+'：「'+st.quote+'」';$('catalogGrid').innerHTML=ITEMS.filter(it=>it.store===id).map(it=>productCard(it)).join('');$('catalogNote').textContent=id==='cafe'?'用餐立即消費並恢復狀態；飽足、精神、心情上限均為 100。':id==='hotel'?'住宿前進一個遊戲日，恢復精神；不會改變真實彩券的開獎時間。':'購買後收進「我的生活」，可隨時更換使用。收藏資產按購入價計入遊戲淨資產，本版不提供轉售。';}
function renderLifeHud(){const l=state?.life;if(!l)return;$('townDay').textContent='DAY '+l.day;$('lifeHud').innerHTML=[['飽足',l.hunger],['精神',l.energy],['心情',l.joy]].map(([n,v])=>'<div class="life-meter"><label>'+n+'<span>'+Math.round(v)+'</span></label><i><b style="width:'+v+'%"></b></i></div>').join('');const car=ITEMS.find(it=>it.id===l.equippedCar);$('driveToggle').textContent=car?(town?.driving?'停車・改步行':'開車・'+car.name):'步行中';renderChronoHUD();}
function purchaseLife(id){const it=ITEMS.find(x=>x.id===id);if(!it||!state)return {ok:false,reason:'尚未開始遊戲'};if(state.life.inventory[id])return {ok:false,reason:'這件收藏已經擁有了'};if(state.balance<it.price)return {ok:false,reason:state.savings?'身上現金不足，可以先到銀行提款。':'現金不足，先累積資金再回來看看。'};if(state.life.spent+it.price>MAX)return {ok:false,reason:'已達生活消費上限'};state.balance-=it.price;state.life.spent+=it.price;const l=state.life;l.joy=Math.min(100,l.joy+(it.joy||0));if(it.kind==='food'){l.hunger=Math.min(100,l.hunger+it.hunger);l.energy=Math.min(100,l.energy+it.energy)}else if(it.kind==='stay'){l.energy=100;l.hunger=Math.max(0,l.hunger-8);l.day++}else{l.inventory[it.id]=1;const key={car:'equippedCar',house:'equippedHome',luxury:'equippedLuxury'}[it.kind];l[key]=it.id;}const text=LIFE_STORES[it.store].name+'・'+it.name;log(text,-it.price);l.history.unshift({text,amount:it.price,at:new Date().toISOString()});l.history=l.history.slice(0,80);persist();updateStats();renderLifeStore(it.store);renderAssets();renderLifeHud();return {ok:true,item:it};}
function equipLife(id){const it=ITEMS.find(x=>x.id===id);if(!state?.life?.inventory[id]||!it)return;state.life[{car:'equippedCar',house:'equippedHome',luxury:'equippedLuxury'}[it.kind]]=id;persist();renderAssets();if(page==='life')renderLifeStore(lifeStore);renderLifeHud();toast('已'+{car:'換開 ',house:'搬進 ',luxury:'配戴 '}[it.kind]+it.name);}
function renderAssets(){if(!state?.life)return;const l=state.life,owned=ITEMS.filter(it=>l.inventory[it.id]),home=ITEMS.find(it=>it.id===l.equippedHome);$('assetsSummary').textContent='DAY '+l.day+' · 已收藏 '+owned.length+' 件資產 · 累計生活消費 NT$ '+money(l.spent)+' · 收藏原價 NT$ '+money(assetValue(state));$('homePanel').innerHTML=home?'<div class="home-panel">'+itemArt(home)+'<div><h3>'+home.name+'</h3><p>你在灣彩的家。回家走到床邊，就能免費休息。</p><button class="secondary" id="visitHome">回家看看 →</button></div></div>':'<div class="home-panel"><div><h3>還在尋找一個家。</h3><p>可以先去灣畔旅館過夜，或到好日子房屋挑選自己的住所。</p><button class="chip" data-walk="estate">走去看房 →</button></div></div>';$('assetGrid').innerHTML=owned.filter(it=>assetTab==='all'||it.kind===assetTab).map(it=>productCard(it,true)).join('')||'<div class="empty" style="grid-column:1/-1">這裡還空著，慢慢把喜歡的生活帶回來。</div>';$('lifeLedger').innerHTML=ledgerMarkup(l.history.map(x=>({...x,amount:-x.amount})));document.querySelectorAll('[data-asset-tab]').forEach(b=>b.classList.toggle('active',b.dataset.assetTab===assetTab));}
function sleepHome(){if(!state?.life?.equippedHome)return false;state.life.day++;state.life.energy=100;state.life.hunger=Math.max(0,state.life.hunger-8);state.life.joy=Math.min(100,state.life.joy+15);state.life.history.unshift({text:'在自己的家好好睡了一晚',amount:0,at:new Date().toISOString()});state.life.history=state.life.history.slice(0,80);persist();updateStats();renderLifeHud();toast('睡飽了，今天是 DAY '+state.life.day+'。');return true;}
document.addEventListener('click',e=>{let b;if(b=e.target.closest('[data-life-buy]')){if(!state)return $('startDialog').showModal();const it=ITEMS.find(it=>it.id===b.dataset.lifeBuy);pendingLifeItem=it.id;$('lifeConfirmTitle').textContent=it.kind==='food'?'今天，就吃這一道。':it.kind==='stay'?'今晚，睡個好覺。':'把'+it.name+'帶回生活。';$('lifeConfirmBody').innerHTML=esc(it.name)+'<br>'+esc(LIFE_STORES[it.store].name)+' · NT$ '+money(it.price)+'<br>'+effectText(it)+'<br>付款後現金 NT$ '+money(state.balance-it.price)+(state.balance<it.price?'<p class="warning">目前現金不足，請先到銀行提款或累積資金。</p>':'');$('confirmLifeBuy').disabled=state.balance<it.price;$('lifeConfirm').showModal();return}if(b=e.target.closest('[data-equip]'))return equipLife(b.dataset.equip);if(b=e.target.closest('[data-asset-tab]')){assetTab=b.dataset.assetTab;return renderAssets()}if(e.target.closest('#visitHome')){closeTownPanel();if(town.indoor)exitBuilding();setTimeout(()=>walkToBuilding('home'),350)}if(b=e.target.closest('[data-walk]')){closeTownPanel();if(town.indoor)exitBuilding();setTimeout(()=>walkToBuilding(b.dataset.walk),350)}});
$('cancelLifeBuy').onclick=()=>$('lifeConfirm').close();$('confirmLifeBuy').onclick=()=>{const id=pendingLifeItem;pendingLifeItem=null;$('lifeConfirm').close();if(!id)return;const r=purchaseLife(id);if(!r.ok)return toast(r.reason);const it=r.item;toast(it.kind==='food'?'吃飽了！'+it.name+'，慢慢享用。':it.kind==='stay'?'晚安。醒來已是 DAY '+state.life.day+'，精神恢復了。':it.kind==='house'?'鑰匙交給你了。到「我的生活」可以回家。':it.kind==='car'?'交車完成！回到鎮上按「開車」就能駕駛。':'已配戴 '+it.name+'，出門看看吧。');};

const SHOPS={harbor:{name:'灣彩・港口店',short:'灣彩港口店',staff:'阿海伯',role:'在地老闆',tag:'港口轉角・老字號',note:'收音機播著老歌，海風吹過紅白棚。',caption:'海風、老收音機，還有一張陪你等開獎的椅子。',stamp:'港邊好彩頭',hello:'少年仔，來喔！海風這麼大，先坐下慢慢選，號碼咱不急。',back:'又來啦！熟面孔不用客氣，老位子幫你留著。',lines:['我在這邊開店二十幾年，最熱鬧的時候，就是大家一起等開獎。','今天的海風不錯。要不要讓我幫你隨機挑一注？手氣嘛，誰知道呢。','買多少都可以慢慢算，別忘了看一下自己的現金跟欠款。'],pick:'好，這一注幫你挑好了。純電腦隨機，阿伯可沒有通天本領喔。'},temple:{name:'金旺來彩券行',short:'金旺來彩券',staff:'小晴',role:'活力店員',tag:'廟口旁邊・熱鬧小店',note:'黃澄澄的招牌，店員的笑聲比鈴鐺還響。',caption:'廟口的香氣飄進店裡，櫃檯旁擺著一顆金鳳梨。',stamp:'好運旺旺來',hello:'歡迎光臨金旺來！我是小晴，今天想小試手氣，還是把發財夢放大？',back:'你回來啦！今天還是老樣子，還是想換個玩法？',lines:['我們店名很旺，但每間店中獎機率都一樣啦。笑得開心倒是真的！','你要包牌也行，我幫你把每一組算清楚。不過包了也不一定會賺喔。','選號選到頭昏的話，按「請店員選一注」，我來幫你按電腦。'],pick:'叮！你的一組隨機幸運號碼好了，看看喜不喜歡！'},night:{name:'夜貓子投注站',short:'夜貓子投注站',staff:'阿哲',role:'夜班店員',tag:'夜市巷口・深夜風格',note:'霓虹微亮，阿哲正慢慢喝著他的冰美式。',caption:'紫色招牌亮著，電視播著獎號，冰美式還剩半杯。',stamp:'NIGHT OWL CLUB',hello:'嗨，我阿哲。先坐，想玩賓果還是等晚上的大獎？',back:'又見面了。你的彩券都在紀錄裡，放心，沒漏掉。',lines:['這裡雖然是夜貓子，簽注截止時間一樣照官方，不能偷跑喔。','想看一億會買到什麼結果？歷史挑戰可以直接試，不用等晚上。','我不看明牌，只幫你把號碼和帳算對。電腦選號要來一注嗎？'],pick:'選好了。沒有神秘演算法，就是一注乾乾淨淨的隨機號碼。'}};
