function migrateSave(s){if(!s)return;migrateTime(s);migrateLife(s);s.savings??=0;s.currentShop=SHOPS[s.currentShop]?s.currentShop:'harbor';s.visits=s.visits&&typeof s.visits==='object'&&!Array.isArray(s.visits)?s.visits:{};}
