migrateSave(state);
function sceneMarkup(type,title,caption,quote){const who=SHOPS[type]||STAFF[type];return '<div class="scene" data-theme="'+type+'"><div class="scene-copy"><div class="scene-breadcrumb"><button data-visit="street">← 回到街區</button><span>／ '+(SHOPS[type]?'投注站':type==='bank'?'銀行':'地下錢莊')+'</span></div><h2>'+title+'</h2><div class="scene-caption">'+caption+'</div><div class="clerk-name">'+who.staff+'<span class="staff-pill">'+who.role+'</span></div><p class="dialogue" id="'+type+'Dialogue">'+quote+'</p><div class="scene-actions"><button data-chat="'+type+'">聊兩句</button>'+(SHOPS[type]?'<button data-clerk-pick="'+type+'">請店員選一注</button><button data-visit="street">換一間逛逛</button>':'<button data-visit="street">回街上逛逛</button>')+'</div></div><div class="scene-room"><span class="room-poster">'+(SHOPS[type]?SHOPS[type].stamp:type==='bank'?'您的資金・妥善保管':'有借有還・帳要清楚')+'</span>'+avatar(type)+'<span class="counter-label">'+(SHOPS[type]?'LOTTERY COUNTER':type==='bank'?'灣彩銀行・服務櫃檯':'金滿貫・私人辦公室')+'</span></div></div>';}
function renderStreet(){$('shopCards').innerHTML=Object.entries(SHOPS).map(([id,s])=>{const bought=state?.tickets.filter(t=>t.shopId===id).reduce((n,t)=>n+t.count,0)||0;return '<button class="place-card shop-card" data-theme="'+id+'" data-shop="'+id+'"><div class="shopfront" aria-hidden="true"><div class="front-building"><div class="front-sign">'+s.short+'<small>WAN TSAI · LOTTERY</small></div><div class="front-awning"></div><div class="front-window">'+avatar(id)+'<span class="window-sticker">'+s.stamp+'</span></div><div class="front-door"></div></div><div class="street-pots"></div></div><div class="place-info"><span class="place-category">'+s.tag+'</span><h3>'+s.name+'</h3><p>'+s.note+'</p><div class="place-bottom"><strong>找'+s.staff+'簽注 →</strong><span>'+(bought?'已在這裡買 '+money(bought)+' 注':s.staff+'在店裡等你')+'</span></div></div></button>'}).join('');$('bankMini').innerHTML=avatar('bank');$('lenderMini').innerHTML=avatar('lender');}
function renderShop(quote){const s=SHOPS[currentShop];$('shopScene').innerHTML=sceneMarkup(currentShop,s.name,s.caption,quote||s.hello);$('shopLocation').textContent=s.name+' ／ '+s.staff+'為你服務';$('rStore').textContent=s.name+' · 經手人 '+s.staff;$('receiptShop').textContent=s.name;}
function enterShop(id){if(!SHOPS[id])return;currentShop=id;chatIndex=0;let repeat=false;if(state){repeat=(Number(state.visits[id])||0)>0;state.visits[id]=(Number(state.visits[id])||0)+1;state.currentShop=id;persist();}renderShop(repeat?SHOPS[id].back:SHOPS[id].hello);setPage('hall');}
function renderServices(){$('bankScene').innerHTML=sceneMarkup('bank','灣彩銀行','把錢存好，讓每一筆資金都有去處。','您好，我是林專員。要辦理存款、提款，還是查一下最近的資金流水？');$('lenderScene').innerHTML=sceneMarkup('lender','金滿貫地下錢莊','巷子底、鐵門後，桌上永遠攤著一本帳。','坐。要借多少、還多少，說個數字。遊戲裡不收利息，欠多少就記多少。');}
const SERVICE_LINES={bank:['存在銀行裡的錢不會直接拿來簽注，出門前記得先辦理提款。','現金、存款和收藏購入價加起來，再扣掉借款，就是你現在的遊戲淨資產。','這裡的存款沒有利息，也不收手續費。要查記錄，我幫您翻存摺。'],lender:['借來的現金不是賺來的。錢放進口袋，帳上的欠款也一起增加。','我這裡是遊戲場景，沒有真實借貸。要還多少，就在帳本上扣多少。','有錢就慢慢還。銀行還有存款的話，得先去領出來才能拿來還我。']};
document.addEventListener('click',e=>{const shop=e.target.closest('[data-shop]'),visit=e.target.closest('[data-visit]'),chat=e.target.closest('[data-chat]'),pick=e.target.closest('[data-clerk-pick]');if(shop)return enterShop(shop.dataset.shop);if(visit){if(visit.dataset.visit==='street'&&town.indoor)return exitBuilding();return setPage(visit.dataset.visit);}if(chat){const id=chat.dataset.chat,lines=SHOPS[id]?.lines||SERVICE_LINES[id];$(id+'Dialogue').textContent=lines[(chatIndex++)%lines.length];return}if(pick){kind='manual';renderForm();$('quickPick').click();$(currentShop+'Dialogue').textContent=SHOPS[currentShop].pick;toast(SHOPS[currentShop].staff+'幫你選好一注了，確認後再簽注。')}});
function ledgerMarkup(items){return items.map(l=>'<div class="log"><div>'+esc(l.text)+'<br><small class="small">'+new Date(l.at).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false})+'</small></div><b class="'+(l.amount<0?'neg':'pos')+'">'+(l.amount>=0?'+':'')+money(l.amount)+'</b></div>').join('')||'<p class="help">帳本乾乾淨淨，還沒有往來紀錄。</p>';}
function renderBank(){const s=state||{balance:0,savings:0,logs:[]};$('bankCash').textContent='NT$ '+money(s.balance);$('bankSavings').textContent='NT$ '+money(s.savings||0);$('ledger').innerHTML=ledgerMarkup(s.logs.slice(0,30));}
function renderLender(){const s=state||{debt:0,logs:[]};$('lenderDebt').textContent='NT$ '+money(s.debt);$('loanLedger').innerHTML=ledgerMarkup(s.logs.filter(l=>/借|還|錢莊/.test(l.text)).slice(0,30));}
function transferBank(withdraw){if(!state)return $('startDialog').showModal();const n=Number($('bankAmount').value);if(!Number.isSafeInteger(n)||n<1||n>MAX)return toast('請輸入有效的整數金額。');if(withdraw&&n>state.savings){$('bankDialogue').textContent='您的存款餘額沒有那麼多，請再確認一下金額。';return toast('銀行存款不足。')}if(!withdraw&&n>state.balance){$('bankDialogue').textContent='您身上的現金不足以存入這個金額，請再確認一下。';return toast('身上現金不足。')}if(withdraw){state.savings-=n;state.balance+=n;log('灣彩銀行・提領存款',n)}else{state.balance-=n;state.savings+=n;log('灣彩銀行・存入現金',-n)}persist();updateStats();$('bankDialogue').textContent='已為您'+(withdraw?'提領':'存入')+' '+money(n)+' 元。您的銀行存款還有 '+money(state.savings)+' 元，請核對。';toast(withdraw?'提款完成，現金已領到手。':'存款完成，錢已收進銀行。');}
$('deposit').onclick=()=>transferBank(false);$('withdraw').onclick=()=>transferBank(true);document.querySelectorAll('[data-bank-amount]').forEach(b=>b.onclick=()=>$('bankAmount').value=b.dataset.bankAmount);$('bankAllCash').onclick=()=>$('bankAmount').value=state?.balance||0;$('bankAllSavings').onclick=()=>$('bankAmount').value=state?.savings||0;

function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4300)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('瀏覽器無法保存，請先匯出存檔備份。');return false}}
function log(text,amount){state.logs.unshift({text,amount,at:new Date().toISOString()});state.logs=state.logs.slice(0,150)}
function updateStats(){const s=state||{balance:0,savings:0,spent:0,won:0,debt:0,tickets:[]};const net=lifeNet(s);$('balance').innerHTML='<small>NT$</small>'+money(s.balance);$('savingsHint').textContent='銀行存款 NT$ '+money(s.savings||0);$('spent').innerHTML='<small>NT$</small>'+money(s.spent);$('won').innerHTML='<small>NT$</small>'+money(s.won);$('net').innerHTML='<small>NT$</small>'+money(net);$('net').className='value '+(net<0?'neg':'');$('debt').textContent='錢莊欠款 NT$ '+money(s.debt);$('totalTickets').textContent='共 '+money(s.tickets.reduce((a,t)=>a+t.count,0))+' 注的期待';$('roi').textContent='遊戲盈虧 '+(s.won-s.spent>=0?'+':'')+money(s.won-s.spent);$('pendingNav').textContent=s.tickets.filter(t=>!t.result).length||'';renderBank();renderLender();if(state?.life){renderLifeHud();updateTownNavigation();renderChronoHUD();}}
function setPage(p){if(p==='wallet')p='bank';if(p==='street'){closeTownPanel();return}if(p==='hall'&&town.indoor!==currentShop){walkToBuilding(currentShop);return}if(['bank','lender'].includes(p)&&town.indoor!==p){walkToBuilding(p);return}if(!['hall','tickets','bank','lender','rules','life','assets'].includes(p))return;page=p;document.querySelectorAll('.page').forEach(e=>e.classList.toggle('hidden',e.id!==p));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===p));if(p==='tickets')renderTickets();if(p==='bank')renderBank();if(p==='lender')renderLender();if(p==='life')renderLifeStore(lifeStore);if(p==='assets')renderAssets();openTownPanel(p);}
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page)};
$('games').innerHTML=Object.entries(C).map(([id,c],i)=>'<button class="game '+(id===game?'active':'')+'" data-game="'+id+'"><span class="gicon">'+['539','大樂透','威力彩','BINGO'][i]+'</span><span class="gname">'+c.name+'</span><small>每注 '+c.price+' 元 · '+['週一至六','每週二、五','每週一、四','每 5 分鐘'][i]+'</small></button>').join('');
$('games').onclick=e=>{const b=e.target.closest('[data-game]');if(!b||busy)return;if(isInPast())return toast('這次手機鎖定了 '+C[state.timeTravel.destination.game].name+'，換彩券請另選穿越座標。');game=b.dataset.game;selected=[];second=0;document.querySelectorAll('.game').forEach(e=>e.classList.toggle('active',e.dataset.game===game));renderForm();loadDraws()};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(isInPast()&&b.dataset.mode!=='travel')return toast('你正在過去，請先用手機返回原時間線。');mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(e=>e.classList.toggle('active',e===b));$('historyControls').classList.toggle('hidden',mode!=='history');if(mode==='live')loadDraws();else renderTarget();updateCost()});
document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;renderForm()});
$('stars').innerHTML=Array.from({length:10},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+' 星</option>').join('');$('stars').onchange=()=>{stars=+$('stars').value;selected=[];renderForm()};
function choose(n,k){let r=1;for(let i=1;i<=k;i++)r=r*(n-i+1)/i;return Math.round(r)}
function count(){if(kind==='cover')return choose(C[game].max,game==='bingo'?stars:C[game].pick)*(game==='power'?8:1);return Number($(kind==='manual'?'manualCount':'batchCount').value)}
function renderForm(){let c=C[game],pick=game==='bingo'?stars:c.pick;document.querySelectorAll('[data-kind]').forEach(e=>e.classList.toggle('active',e.dataset.kind===kind));['manual','random','cover'].forEach(k=>$(k+'Area').classList.toggle('hidden',kind!==k));$('bingoSetting').classList.toggle('hidden',game!=='bingo');$('second').classList.toggle('hidden',game!=='power');$('gameRule').textContent=game==='power'?'第一區 6 碼＋第二區 1 碼':'從 '+c.max+' 個號碼選 '+pick+' 個';$('selectCount').textContent='已選 '+selected.length+' / '+pick+' 個號碼';$('numbers').innerHTML=Array.from({length:c.max},(_,i)=>'<button class="num '+(selected.includes(i+1)?'on':'')+'" data-n="'+(i+1)+'" aria-pressed="'+selected.includes(i+1)+'">'+String(i+1).padStart(2,'0')+'</button>').join('');$('secondNumbers').innerHTML=Array.from({length:8},(_,i)=>'<button class="num '+(second===i+1?'on':'')+'" data-s="'+(i+1)+'" aria-pressed="'+(second===i+1)+'">'+String(i+1).padStart(2,'0')+'</button>').join('');$('batchHelp').textContent='一億就能買 '+money(Math.floor(1e8/c.price))+' 注 '+c.name+'。每筆最多 1 億注。';const cover=choose(c.max,pick)*(game==='power'?8:1);$('coverCount').textContent=money(cover)+' 注';$('coverHelp').textContent='一次買齊所有不重複組合'+(game==='power'?'，包含全部第二區':'')+'，花費 NT$ '+money(cover*c.price)+'。'+(cover>1e8?'組數超過本版每筆上限，請降低賓果星數。':'每一組號碼都買一次，獎池仍可能需要均分，包牌不代表獲利。');updateCost()}
$('numbers').onclick=e=>{const b=e.target.closest('[data-n]');if(!b)return;const n=+b.dataset.n,p=game==='bingo'?stars:C[game].pick;if(selected.includes(n))selected=selected.filter(x=>x!==n);else if(selected.length<p)selected.push(n);else return toast('這個玩法只選 '+p+' 個號碼。');renderForm()};$('secondNumbers').onclick=e=>{const b=e.target.closest('[data-s]');if(b){second=+b.dataset.s;renderForm()}};
$('quickPick').onclick=()=>{selected=[];const p=game==='bingo'?stars:C[game].pick;while(selected.length<p){const a=1+Math.floor(Math.random()*C[game].max);if(!selected.includes(a))selected.push(a)}if(game==='power')second=1+Math.floor(Math.random()*8);renderForm()};$('clearPick').onclick=()=>{selected=[];second=0;renderForm()};
['manualCount','batchCount'].forEach(id=>$(id).oninput=updateCost);document.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>{$('batchCount').value=Math.floor(+b.dataset.budget/C[game].price);updateCost()});
function updateCost(){let n=count(),valid=Number.isSafeInteger(n)&&n>0&&n<=1e8,cost=n*C[game].price;$('cost').innerHTML='<small>NT$</small>'+(valid?money(cost):'—');$('rGame').textContent=C[game].name;$('rMode').textContent=mode==='travel'?'穿越簽注':mode==='live'?'真實追獎':'歷史挑戰';$('rKind').textContent={manual:'自選號碼',random:'大量電腦選號',cover:'全部包牌'}[kind];$('rCount').textContent=valid?money(n)+' 注':'—';$('rCost').textContent=valid?'$ '+money(cost):'—';$('buy').disabled=busy||!valid||!target||loading||(isInPast()&&!travelTicketAllowed());$('buy').textContent=busy?'正在逐注對獎…':'確認投注 →'}
function localDate(d=new Date()){return new Date(d.getTime()+28800000).toISOString().slice(0,10)}
function nextTarget(){if(!draws.length)return null;const now=Date.now(),c=C[game];if(game==='bingo'){const latest=draws[0],min=now+300000;let t=new Date(latest.time).getTime()+300000,period=+latest.period+1;for(let i=0;i<500;i++,t+=300000){let dt=new Date(t+28800000),minute=dt.getUTCHours()*60+dt.getUTCMinutes();if(minute<425||minute>1435)continue;if(t>min)return {period:String(period),date:localDate(new Date(t)),time:new Date(t).toISOString()};period++}return null;}for(let i=0;i<15;i++){let d=new Date(now+28800000);d.setUTCDate(d.getUTCDate()+i);let date=d.toISOString().slice(0,10);if(c.days.includes(d.getUTCDay())&&new Date(date+'T20:00:00+08:00').getTime()>now)return {date,time:date+'T20:30:00+08:00',period:null}}return null}
function renderTarget(){if(isInPast()){target=state.timeTravel.destination.draw;$('drawInfo').innerHTML='<strong>穿越簽注 · '+esc(target.date)+' · 第 '+esc(target.period)+' 期</strong><br>'+ (state.timeTravel.phase==='before'?'你正站在開獎前。簽好一張彩券，再用手機快轉開獎。':state.timeTravel.phase==='await'?'彩券已簽好。請按「快轉開獎」，讓時間前進。':'本期已結束。打開手機，返回現在或選擇下一個時點。');updateCost();return;}if(mode==='history'){const old=$('drawSelect').value;$('drawSelect').innerHTML=draws.map(d=>'<option value="'+d.period+'">'+d.date+' · 第 '+d.period+' 期</option>').join('');if(draws.some(d=>d.period===old))$('drawSelect').value=old;target=draws.find(d=>d.period===$('drawSelect').value)||null;$('drawInfo').innerHTML=target?'<strong>歷史挑戰 · 第 '+target.period+' 期</strong><br>使用已公布的官方真實獎號，下注後立即揭曉。':'尚無可用的歷史開獎資料';}else{target=nextTarget();$('drawInfo').innerHTML=target?'<strong>真實追獎 · '+target.date+(target.period?' 第 '+target.period+' 期':'')+'</strong><br>預定 '+new Date(target.time).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false})+' 開獎 · 官方公布後自動對獎。':'官方資料尚未取得，暫停簽注。';}updateCost()}
$('drawSelect').onchange=()=>{target=draws.find(d=>d.period===$('drawSelect').value);renderTarget()};
let loadId=0;async function fetchDraws(g,date){const r=await fetch('/api/draws?game='+g+(date?'&date='+date:''));const j=await r.json();if(!r.ok)throw Error(j.error||'官方資料連線失敗');return j}
async function loadDraws(date){if(isInPast()){++loadId;applyTimeTarget();return;}const id=++loadId,g=game;loading=true;target=null;updateCost();$('sourceStatus').textContent='正在同步台灣彩券官方資料…';try{const j=await fetchDraws(g,date);if(id!==loadId)return;draws=j.draws;$('drawSelect').innerHTML='';const latest=draws[0];$('latestTitle').textContent=(date?'查詢期別':'官方最新開獎')+' · '+C[g].name;$('latestBalls').innerHTML=latest?latest.numbers.map(n=>'<span class="ball">'+esc(String(n).padStart(2,'0'))+'</span>').join('')+(g!=='cash'&&g!=='bingo'?'<span class="ball special">'+String(latest.special).padStart(2,'0')+'</span>':''):'';$('sourceStatus').textContent=latest?'第 '+latest.period+' 期 · '+latest.date+'\n台灣彩券官方資料 · '+new Date(j.fetchedAt).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour12:false})+' 更新':'該日期尚無官方結果';$('historyDate').value=date||localDate();loading=false;renderTarget();}catch(e){if(id!==loadId)return;draws=[];loading=false;$('sourceStatus').textContent='連線未完成。未使用隨機號碼代替官方獎號。';$('drawInfo').textContent=e.message;target=null;updateCost();}}
$('refresh').onclick=()=>loadDraws(mode==='history'?$('historyDate').value:undefined);$('queryDate').onclick=()=>loadDraws($('historyDate').value);
function initSave(amount){state={version:1,balance:amount,savings:0,initial:amount,debt:0,spent:0,won:0,tickets:[],logs:[],currentShop:'harbor',visits:{}};currentShop='harbor';migrateSave(state);renderShop();town.indoor=null;town.x=800;town.y=375;town.driving=false;town.path=[];setPage('street');log('初始資金',amount);persist();updateStats()}
$('startGame').onclick=()=>{const n=Number($('startAmount').value);if(!Number.isSafeInteger(n)||n<0||n>1e12)return toast('請輸入 0～1 兆的整數初始資金。');initSave(n);$('startDialog').close();toast('前面好像有一支發亮的手機。走近看看吧。')};document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>$('startAmount').value=b.dataset.start);$('startDialog').addEventListener('cancel',e=>{if(!state)e.preventDefault()});
$('buy').onclick=()=>{if(!state)return $('startDialog').showModal();if(isInPast()&&!travelTicketAllowed())return toast('這一期已簽注，打開手機快轉到開獎時刻。');if(busy||!target)return;let n=count(),c=C[game],p=game==='bingo'?stars:c.pick;if(!Number.isSafeInteger(n)||n<1||n>1e8)return toast('每筆請輸入 1～1 億注的整數。');if(kind==='manual'&&(selected.length!==p||(game==='power'&&!second)))return toast('請選滿 '+p+' 個號碼'+(game==='power'?'與第二區號碼':'')+'。');if(state.spent+n*c.price>MAX)return toast('已達累計投注上限，請匯出存檔後重新開始。');if(n*c.price>state.balance){toast(state.savings?'現金不足，可以先到銀行提款。':'現金不足，先去錢莊找豹哥週轉。');return setPage(state.savings?'bank':'lender')}const live=mode==='live'?nextTarget():target;if(!live)return toast('未取得期別，請先更新資料。');pendingBuy={id:crypto.randomUUID(),tripId:isInPast()?state.timeTravel.tripId:null,shopId:currentShop,staffName:SHOPS[currentShop].staff,shopName:SHOPS[currentShop].name,game,mode,kind,stars,pick:p,count:n,cost:n*c.price,numbers:[...selected].sort((a,b)=>a-b),second,seed:crypto.getRandomValues(new Uint32Array(1))[0]||1,target:structuredClone(live),createdAt:new Date().toISOString(),result:null};$('confirmBody').innerHTML=esc(SHOPS[currentShop].name)+' · '+esc(SHOPS[currentShop].staff)+'為你開單<br>'+esc(c.name)+' · '+(mode==='travel'?'穿越簽注':mode==='live'?'真實追獎':'歷史挑戰')+'<br>'+esc(live.date)+(live.period?' · 第 '+esc(live.period)+' 期':'')+'<br>'+money(n)+' 注 · 共 NT$ '+money(pendingBuy.cost)+'<br>簽注後可用資金：NT$ '+money(state.balance-pendingBuy.cost);$('confirmDialog').showModal()};$('cancelBuy').onclick=()=>$('confirmDialog').close();
$('confirmBuy').onclick=async()=>{const t=pendingBuy;if(!t||busy||t.cost>state.balance)return;if(t.mode==='travel'&&(!travelTicketAllowed()||t.tripId!==state.timeTravel.tripId)){pendingBuy=null;$('confirmDialog').close();return toast('時間線已改變，請重新確認彩券。')}const now=Date.now();if(t.mode==='live'&&new Date(t.target.time).getTime()-(t.game==='bingo'?300000:1800000)<=now){$('confirmDialog').close();renderTarget();return toast('該期已截止，請重新確認下一期。')}state.balance-=t.cost;state.spent+=t.cost;state.tickets.unshift(t);if(t.mode==='travel'){state.timeTravel.ticketId=t.id;state.timeTravel.phase='await';recordTime(t.target.date+'・在'+t.shopName+'簽下一張彩券');}log((t.shopName||'灣彩投注站')+'・'+C[t.game].name+' '+money(t.count)+' 注',-t.cost);persist();pendingBuy=null;$('confirmDialog').close();updateStats();$(currentShop+'Dialogue').textContent=SHOPS[currentShop].staff+'：彩券開好了，這筆 '+money(t.count)+' 注、共 '+money(t.cost)+' 元，幫你收進我的彩券囉。';toast('已簽注！'+(t.mode==='history'?'開始逐注對獎。':t.mode==='travel'?'打開時空手機，快轉到開獎時刻。':'彩券已保存，等待官方開獎。'));if(t.mode==='history'){await settle(t,t.target);setPage('tickets');if(t.result)showResult(t)}else if(page==='tickets')renderTickets()};
function simulation(job,report){let seed=job.seed>>>0;function rand(n){let limit=Math.floor(4294967296/n)*n,x;do{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;x=seed>>>0;}while(x>=limit);return x%n}const c=job.c,max=c.max,pick=job.pick,winning=new Set(job.draw.numbers),hist={},samples=[],wins=[],comb=Array.from({length:pick},(_,i)=>i+1);let extra=1;function rank(nums,s){let m=0;for(const x of nums)if(winning.has(x))m++;if(job.game==='cash')return m>=2?String(5-m):null;if(job.game==='bingo')return job.draw.prizes[job.stars+':'+m]>0?String(m):null;let b=job.game==='power'?s===job.draw.special:nums.includes(job.draw.special);if(job.game==='lotto'){if(m===6)return'0';if(m===5)return b?'1':'2';if(m===4)return b?'3':'4';if(m===3)return b?'5':'7';if(m===2&&b)return'6';return null;}if(m===6)return b?'0':'1';if(m===5)return b?'2':'3';if(m===4)return b?'4':'5';if(m===3)return b?'6':'8';if(m===2&&b)return'7';if(m===1&&b)return'9';return null;}
function ticket(i){let nums,s=0;if(job.kind==='manual'){nums=job.numbers;s=job.second;}else if(job.kind==='cover'){nums=comb.slice();s=job.game==='power'?extra:0;if(job.game==='power'&&extra<8)extra++;else{extra=1;let j=pick-1;while(j>=0&&comb[j]===max-pick+j+1)j--;if(j>=0){comb[j]++;for(let k=j+1;k<pick;k++)comb[k]=comb[k-1]+1}}}else{nums=[];while(nums.length<pick){let x=rand(max)+1;if(!nums.includes(x))nums.push(x)}nums.sort((a,b)=>a-b);if(job.game==='power')s=rand(8)+1;}return {index:i+1,numbers:nums,second:s};}
if(job.preview){let out=[];for(let i=0;i<job.previewEnd;i++){let t=ticket(i);if(i>=job.previewStart)out.push(t)}return {preview:out};}
if(job.kind==='manual'){const r=rank(job.numbers,job.second);if(r!==null)hist[r]=job.count;samples.push(ticket(0));if(r!==null)wins.push({...samples[0],band:r});report(100);}else{for(let i=0;i<job.count;i++){const t=ticket(i),r=rank(t.numbers,t.second);if(i<5)samples.push(t);if(r!==null){hist[r]=(hist[r]||0)+1;if(wins.length<8)wins.push({...t,band:r})}if(i%100000===0)report(i/job.count*100)}report(100)}return {hist,samples,wins};}
let calcWorker;function compute(job){return new Promise((resolve,reject)=>{const source='const simulation='+simulation.toString()+';onmessage=e=>{try{postMessage({done:simulation(e.data,p=>postMessage({progress:p}))})}catch(e){postMessage({error:e.message})}}';const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'})),w=new Worker(url);URL.revokeObjectURL(url);calcWorker=w;w.onmessage=e=>{if(e.data.progress!=null){$('progress').classList.remove('hidden');$('progress').firstElementChild.style.width=e.data.progress+'%';$('progressText').textContent='正在逐注核對 '+money(job.count)+' 注 · '+Math.floor(e.data.progress)+'%';}if(e.data.done){w.terminate();resolve(e.data.done)}if(e.data.error){w.terminate();reject(Error(e.data.error))}};w.onerror=e=>{w.terminate();reject(Error(e.message||'計算中斷'))};w.postMessage(job)})}
function payout(t,d,hist){let rows=[],total=0;const names=t.game==='cash'?['頭獎','貳獎','參獎','肆獎']:t.game==='lotto'?['頭獎','貳獎','參獎','肆獎','伍獎','陸獎','柒獎','普獎']:['頭獎','貳獎','參獎','肆獎','伍獎','陸獎','柒獎','捌獎','玖獎','普獎'];for(const [key,n]of Object.entries(hist)){let band=+key,unit=0,name;if(t.game==='bingo'){unit=d.prizes[t.stars+':'+band];name='中 '+band+' 碼';}else{const p=d.prizes[band];name=names[band];if(t.game==='cash'&&band===0)unit=Math.min(8000000,Math.floor(24000000/(p.winnerCount+n)));else if((t.game==='lotto'&&band<=3)||(t.game==='power'&&band<=1)){const pool=Math.max((p.prize||0)+(p.lastPrize||0),band===0?(t.game==='lotto'?1e8:2e8):0);unit=Math.floor(pool/((p.winnerCount||0)+n));}else unit=p.perPrize;if(!Number.isFinite(unit)||unit<0)throw Error('獎金資料尚未完整');}let sum=unit*n;rows.push({name,n,unit,sum});total+=sum;}return {rows,total};}
async function settle(t,d){if(t.result||busy)return false;if(!d.ready)return false;busy=true;updateCost();try{const r=await compute({...t,c:C[t.game],draw:d});if(t.result)return true;const p=payout(t,d,r.hist);if(!Number.isSafeInteger(p.total)||state.balance+(state.savings||0)+p.total>MAX)throw Error('獎金超出遊戲錢包上限，尚未結算');t.result={...r,...p,draw:d,at:new Date().toISOString()};state.balance+=p.total;state.won+=p.total;log(C[t.game].name+' 第 '+d.period+' 期對獎',p.total);persist();updateStats();if(page==='tickets')renderTickets();toast(p.total?'開獎！獎金 NT$ '+money(p.total)+' 已入帳。':'本次未中獎，彩券結果已保存。');return true}catch(e){toast('對獎未完成：'+e.message+'。彩券保留，可再試一次。');return false}finally{busy=false;$('progress').classList.add('hidden');$('progressText').textContent='';updateCost()}}
function showResult(t){const r=t.result,profit=r.total-t.cost;$('resultTitle').textContent=profit>0?'這次，夢想賺到了。':r.total?'有中獎！來算算賺多少。':'這次，幸運還在路上。';$('resultSubtitle').textContent=C[t.game].name+' · 官方第 '+r.draw.period+' 期 · 共 '+money(t.count)+' 注';$('resultBalls').innerHTML=ballsHTML(r.draw.numbers,t.game==='cash'||t.game==='bingo'?0:r.draw.special);$('resultMoney').textContent='$ '+money(r.total);$('resultProfit').textContent='投注 '+money(t.cost)+' 元 · 損益 '+(profit>0?'+':'')+money(profit)+' 元';$('resultProfit').className=profit<0?'neg':'pos';$('resultDialog').showModal()}
$('closeResult').onclick=()=>$('resultDialog').close();
function ballsHTML(nums,s){return nums.map(n=>'<span class="ball">'+esc(String(n).padStart(2,'0'))+'</span>').join('')+(s?'<span class="ball special">'+String(s).padStart(2,'0')+'</span>':'')}
function renderTickets(){if(!state?.tickets.length){$('ticketList').innerHTML='<div class="panel empty">✦<br>你的第一張發財夢，還沒簽下。<br>回街區找一間投注站，選一組幸運號碼吧。</div>';return} $('ticketList').innerHTML=state.tickets.map(t=>{const r=t.result;return '<article class="ticket"><div class="ticket-top"><strong>'+C[t.game].name+' · '+money(t.count)+' 注</strong><span class="badge">'+(t.mode==='travel'?'時空穿越':t.mode==='live'?'真實追獎':'歷史挑戰')+' · '+(r?'已對獎':'等待官方結果')+'</span></div><div class="help">'+esc(t.target.date)+' '+(t.target.period?'第 '+esc(t.target.period)+' 期':'預定開獎')+' · '+{manual:'自選號碼',random:'電腦隨機',cover:'全部包牌'}[t.kind]+'<br>投注 NT$ '+money(t.cost)+'</div><div class="origin-line">'+(SHOPS[t.shopId]?avatar(t.shopId):'')+'<span>'+esc(t.shopName||'灣彩投注站・原始紀錄')+' · 經手人 '+esc(t.staffName||'原櫃檯店員')+'</span></div>'+(t.kind==='manual'?'<div class="balls" style="margin-top:13px">'+ballsHTML(t.numbers,t.game==='power'?t.second:0)+'</div>':'')+(r?'<div class="details"><span>獎金 <b class="'+(r.total?'pos':'')+'">NT$ '+money(r.total)+'</b></span><span>損益 <b class="'+(r.total-t.cost<0?'neg':'pos')+'">'+money(r.total-t.cost)+'</b></span><span>中獎 '+money(Object.values(r.hist).reduce((a,b)=>a+b,0))+' 注</span></div><details><summary>查看官方獎號與獎金明細</summary><p class="help">官方第 '+esc(r.draw.period)+' 期</p><div class="balls">'+ballsHTML(r.draw.numbers,t.game==='cash'||t.game==='bingo'?0:r.draw.special)+'</div>'+(r.rows.length?'<table><tr><th>獎項</th><th>注數</th><th>每注（元）</th><th>合計（元）</th></tr>'+r.rows.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+money(x.n)+'</td><td>'+money(x.unit)+'</td><td>'+money(x.sum)+'</td></tr>').join('')+'</table>':'<p class="help">沒有符合中獎條件的注數。</p>')+'<p class="help">浮動獎金已加入本筆模擬中獎注數均分，稅前；未重算官方銷售。</p></details>':(t.mode==='travel'?'<p class="help">這張彩券還停在過去。打開時空手機，按「快轉到開獎時刻」才能對獎。</p>':'<p class="help">已扣款並保存。開獎後點「更新並對獎」，或保持網頁開啟自動查詢。</p>'))+'<details><summary>查看每注號碼</summary><p class="help">'+(t.kind==='manual'?'所有注數均為相同號碼。':'以下可逐頁重建投注號碼，每頁 20 注；後段頁數需要較長計算時間。')+'</p><div style="display:flex;gap:8px;align-items:center"><input type="number" min="1" max="'+Math.ceil(t.count/20)+'" value="1" aria-label="彩券頁數" id="previewPage-'+t.id+'" style="width:110px"><span class="small">/ '+money(Math.ceil(t.count/20))+' 頁</span><button class="chip" data-preview="'+t.id+'">讀取號碼</button></div><div id="preview-'+t.id+'"></div></details></article>'}).join('')}
$('ticketList').onclick=async e=>{const b=e.target.closest('[data-preview]');if(!b||busy)return;const t=state.tickets.find(t=>t.id===b.dataset.preview),pageNum=+$('previewPage-'+t.id).value;if(!Number.isInteger(pageNum)||pageNum<1||pageNum>Math.ceil(t.count/20))return toast('請輸入範圍內的頁數');b.disabled=true;b.textContent='正在重建…';try{const r=await compute({...t,c:C[t.game],draw:t.result?.draw||{numbers:[],special:0,prizes:{}},preview:true,previewStart:(pageNum-1)*20,previewEnd:Math.min(pageNum*20,t.count)});$('preview-'+t.id).innerHTML=r.preview.map(x=>'<div class="log"><span>第 '+money(x.index)+' 注</span><span>'+x.numbers.map(n=>String(n).padStart(2,'0')).join(' · ')+(t.game==='power'?' ＋ '+x.second:'')+'</span></div>').join('')}catch(err){toast(err.message)}finally{b.disabled=false;b.textContent='讀取號碼'}};
async function refreshPending(){if(!state||busy||refreshing)return;refreshing=true;$('settleAll').disabled=true;try{const cache={};for(const t of state.tickets.filter(t=>!t.result)){if(busy)break;if(t.mode==='travel')continue;if(t.mode==='history'){await settle(t,t.target);continue}if(new Date(t.target.time).getTime()>Date.now())continue;const key=t.game+':'+(t.game==='bingo'?t.target.date:t.target.date.slice(0,7));try{const ds=cache[key]||(cache[key]=(await fetchDraws(t.game,t.target.date)).draws),d=ds.find(d=>t.game==='bingo'?d.period===t.target.period:d.date===t.target.date);if(d)await settle(t,d)}catch(e){toast(e.message)}}}finally{refreshing=false;$('settleAll').disabled=false;updateStats();if(page==='tickets')renderTickets()}}
$('settleAll').onclick=refreshPending;setInterval(()=>{if(!busy){if(page==='hall'&&mode==='live')loadDraws();refreshPending()}},60000);
document.querySelectorAll('[data-loan]').forEach(b=>b.onclick=()=>$('loanAmount').value=b.dataset.loan);function loan(repay){if(!state)return $('startDialog').showModal();const n=+$('loanAmount').value;if(!Number.isSafeInteger(n)||n<1||n>1e12)return toast('請輸入 1～1 兆的整數金額');if(repay){if(n>state.balance||n>state.debt)return toast('還款金額不可超過身上現金或欠款餘額');state.balance-=n;state.debt-=n;log('金滿貫地下錢莊・償還借款',-n)}else{if(state.balance+(state.savings||0)+n>MAX||state.debt+n>MAX)return toast('已達遊戲資金上限');state.balance+=n;state.debt+=n;log('金滿貫地下錢莊・借入週轉金',n)}persist();updateStats();$('lenderDialogue').textContent=repay?'收到 '+money(n)+' 元，帳上幫你扣掉了。現在還欠 '+money(state.debt)+' 元。':'這 '+money(n)+' 元拿著，記在你帳上了。借款共 '+money(state.debt)+' 元，別和賺到的錢混在一起算。';toast(repay?'豹哥已在帳本記下還款。':'豹哥把現金交給你了，借款已記帳。')};$('borrow').onclick=()=>loan(false);$('repay').onclick=()=>loan(true);
$('newGame').onclick=()=>{if(busy)return toast('請等待本筆對獎完成');if(confirm('重新開始會清除目前所有投注與資金。建議先匯出存檔。確定重開？')){$('startDialog').showModal()}};
$('exportSave').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='wan-tsai-save-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('importSave').onclick=()=>{if(busy||refreshing)return toast('請等對獎完成再匯入');$('saveFile').click()};
function validLifeSave(l){if(!l||typeof l!=='object'||Array.isArray(l)||!l.inventory||typeof l.inventory!=='object'||Array.isArray(l.inventory))return false;for(const k of ['hunger','energy','joy'])if(!Number.isFinite(l[k])||l[k]<0||l[k]>100)return false;if(!Number.isSafeInteger(l.spent)||l.spent<0||l.spent>MAX||!Number.isSafeInteger(l.day)||l.day<1||!Array.isArray(l.history)||l.history.length>80)return false;return l.history.every(x=>x&&typeof x.text==='string'&&Number.isSafeInteger(x.amount)&&x.amount>=0&&typeof x.at==='string')&&Object.entries(l.inventory).every(([k,v])=>/^[a-z]+$/.test(k)&&v===1);}
function validSave(s){if(s?.timeTravel!==undefined&&!validTimeSave(s.timeTravel))return false;if(s?.life!==undefined&&!validLifeSave(s.life))return false;if(s?.savings!==undefined&&(!Number.isSafeInteger(s.savings)||s.savings<0||s.savings>MAX))return false;if(!s||s.version!==1||!Array.isArray(s.tickets)||s.tickets.length>10000||!Array.isArray(s.logs))return false;for(const k of ['balance','initial','debt','spent','won'])if(!Number.isSafeInteger(s[k])||s[k]<0||s[k]>MAX)return false;return s.tickets.every(t=>C[t.game]&&['manual','random','cover'].includes(t.kind)&&['live','history','travel'].includes(t.mode)&&Number.isInteger(t.count)&&t.count>0&&t.count<=1e8&&Number.isInteger(t.seed)&&Array.isArray(t.numbers)&&t.numbers.every(n=>Number.isInteger(n)&&n>=1&&n<=C[t.game].max)&&typeof t.id==='string'&&/^[a-zA-Z0-9-]+$/.test(t.id)&&t.target&&/^\d{4}-\d{2}-\d{2}$/.test(t.target.date)&&Number.isFinite(Date.parse(t.target.time))&&Number.isInteger(t.pick)&&t.pick>=1&&t.pick<=10&&Number.isInteger(t.cost)&&t.cost===t.count*C[t.game].price)}
$('saveFile').onchange=async()=>{const f=$('saveFile').files[0];if(!f)return;try{if(f.size>30e6)throw Error();const s=JSON.parse(await f.text());if(!validSave(s))throw Error();if(confirm('匯入將取代目前遊戲，確定繼續？')){state=s;migrateSave(state);town.indoor=null;town.x=800;town.y=375;town.driving=false;town.path=[];currentShop=state.currentShop;renderShop();persist();updateStats();setPage('street');toast('存檔已匯入，回到小鎮繼續生活。');refreshPending()}}catch{toast('無法讀取這份存檔，請使用灣彩匯出的 JSON 檔。')}finally{$('saveFile').value=''}};
