function townObjects(){const fixed=[{x:711,y:433,w:178,h:110},{x:445,y:514,w:100,h:28},{x:1060,y:514,w:100,h:28}];return BUILDINGS.map(b=>({x:b.x-10,y:b.y-12,w:b.w+20,h:b.h+15})).concat(fixed)}
function isWalkable(x,y,indoor=town.indoor){const world=indoor?ROOM:WORLD;if(x<25||y<35||x>world.w-25||y>world.h-25)return false;if(indoor){if(x<67||x>933||y<125||y>675)return false;if(indoor==='home'){if(x>650&&x<880&&y>160&&y<355)return false;if(x>110&&x<340&&y>170&&y<330)return false;return true}if(y<315&&x>270&&x<740)return false;if(x>80&&x<240&&y>360&&y<485)return false;if(x>780&&x<920&&y>365&&y<495)return false;return true}return !townObjects().some(r=>x>r.x-9&&x<r.x+r.w+9&&y>r.y-9&&y<r.y+r.h+9)}
function routeTown(sx,sy,tx,ty,indoor=town.indoor){const size=20,world=indoor?ROOM:WORLD,cols=Math.floor(world.w/size),rows=Math.floor(world.h/size),index=(x,y)=>y*cols+x;let ax=Math.max(1,Math.min(cols-2,Math.floor(sx/size))),ay=Math.max(2,Math.min(rows-2,Math.floor(sy/size))),bx=Math.max(1,Math.min(cols-2,Math.floor(tx/size))),by=Math.max(2,Math.min(rows-2,Math.floor(ty/size)));if(!isWalkable(bx*size+10,by*size+10,indoor)){let found=false;for(let r=1;r<9&&!found;r++)for(let dx=-r;dx<=r&&!found;dx++)for(let dy=-r;dy<=r;dy++){const x=bx+dx,y=by+dy;if(x>0&&y>1&&x<cols-1&&y<rows-1&&isWalkable(x*size+10,y*size+10,indoor)){bx=x;by=y;found=true;break}}if(!found)return [];}const start=index(ax,ay),end=index(bx,by),queue=[start],prev=new Int32Array(cols*rows).fill(-2);prev[start]=-1;for(let head=0;head<queue.length;head++){const cur=queue[head];if(cur===end)break;const x=cur%cols,y=Math.floor(cur/cols);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy;if(nx<1||ny<2||nx>=cols-1||ny>=rows-1)continue;const n=index(nx,ny);if(prev[n]!==-2||!isWalkable(nx*size+10,ny*size+10,indoor))continue;prev[n]=cur;queue.push(n)}}if(prev[end]===-2)return [];let path=[],i=end;while(i!==start&&i>=0){path.push({x:(i%cols)*size+10,y:Math.floor(i/cols)*size+10});i=prev[i]}return path.reverse();}
function walkToBuilding(id){const b=BUILDINGS.find(b=>b.id===id);if(!b)return;if(id==='home'&&!state?.life?.equippedHome)return toast('先到好日子房屋，買下一個自己的家。');if(town.indoor){exitBuilding();setTimeout(()=>walkToBuilding(id),400);return}town.path=routeTown(town.x,town.y,b.x+b.w/2,b.y+b.h+40,null);town.autoDoor=id;$('townMap').classList.add('hidden');closeTownPanel();if(!town.path.length){if(Math.hypot(town.x-b.x-b.w/2,town.y-b.y-b.h-40)<50)enterBuilding(id);else toast('這裡走不過去，換個位置試試。')}else{setPrompt('正在走向 '+b.name+'…');town.canvas?.focus();}}
