function nearbyTown(){if(!town.indoor&&state&&!state.timeTravel.phoneFound&&Math.hypot(town.x-PHONE_SPOT.x,town.y-PHONE_SPOT.y)<75)return {type:'phone',label:'撿起發亮的手機'};if(town.indoor){if(Math.hypot(town.x-500,town.y-655)<65)return {type:'exit',label:'走出店鋪'};if(town.indoor==='home'){if(Math.hypot(town.x-740,town.y-380)<100)return {type:'sleep',label:'在自己的床上休息'};return null}if(town.y<425&&town.x>325&&town.x<675)return {type:'counter',label:'與'+BUILDINGS.find(b=>b.id===town.indoor).staff+'互動'};return null}return BUILDINGS.map(b=>({...b,dist:Math.hypot(town.x-b.x-b.w/2,town.y-b.y-b.h-38)})).filter(b=>b.dist<75).sort((a,b)=>a.dist-b.dist)[0]||null;}
function interactTown(){if(town.transition||town.panel)return;const n=nearbyTown();if(!n)return toast(town.indoor?'先走近櫃檯；點櫃檯前的地板也能走過去。':'先走到店門前，或點「找店家」帶路。');if(n.type==='phone')return pickupPhone();if(n.type==='exit')return exitBuilding();if(n.type==='sleep')return transitionTown('晚安，好好休息。',()=>{sleepHome();town.x=720;town.y=390});if(n.type==='counter'){const id=town.indoor;if(SHOPS[id])return setPage('hall');if(id==='bank'||id==='lender')return setPage(id);lifeStore=id;renderLifeStore(id);return setPage('life')}enterBuilding(n.id)}
