function drawHuman(g,x,y,color='#b54f3c',phase=0,isPlayer=false){g.save();g.translate(x,y);const bounce=isPlayer&&town.path.length?Math.sin(phase)*1.8:0;g.translate(0,bounce);g.fillStyle='#2e453d33';g.beginPath();g.ellipse(0,4,15,6,0,0,Math.PI*2);g.fill();g.strokeStyle='#3e4b49';g.lineWidth=7;g.lineCap='round';g.beginPath();g.moveTo(-6,-6);g.lineTo(-6-Math.sin(phase)*4,0);g.moveTo(6,-6);g.lineTo(6+Math.sin(phase)*4,0);g.stroke();townRound(g,-13,-31,26,29,7,color);g.fillStyle='#e9be98';g.beginPath();g.arc(0,-43,13,0,Math.PI*2);g.fill();g.fillStyle='#4c443b';g.beginPath();g.arc(0,-47,13,Math.PI,Math.PI*2);g.fill();if(isPlayer){townRound(g,-15,-55,29,10,4,'#b4513d');townRound(g,-17,-48,34,5,2,'#ce6b4e');if(town.dir!=='up'){g.fillStyle='#463f35';g.fillRect(-5,-43,2,2);g.fillRect(4,-43,2,2)}const wear=state?.life?.equippedLuxury;if(wear==='wallet'||wear==='bag'){townRound(g,9,-26,13,18,3,wear==='bag'?'#c2a066':'#8f6041');g.strokeStyle='#dfc78e';g.lineWidth=2;g.beginPath();g.moveTo(-10,-27);g.lineTo(15,-17);g.stroke()}if(wear==='watch'){g.fillStyle='#d8ca87';g.fillRect(-17,-16,7,4)}if(wear==='necklace'){g.strokeStyle='#eedb93';g.lineWidth=2;g.beginPath();g.arc(0,-27,6,0,Math.PI);g.stroke();g.fillStyle='#fff7ec';g.beginPath();g.arc(0,-20,3+Math.sin(phase*.3)*.6,0,Math.PI*2);g.fill();}}g.restore()}
function townBackground(g,time){const key=(town.indoor||'outside')+':'+(state?.life?.equippedHome||'')+':'+(state?.life?.equippedCar||'')+':'+(town.portraitVersion||0)+':'+(state?.timeTravel?.active?state.timeTravel.destination.draw.date:'present');if(!town.sceneCache||town.sceneCache.key!==key){const c=document.createElement('canvas'),w=town.indoor?ROOM:WORLD;c.width=w.w;c.height=w.h;const cg=c.getContext('2d');if(town.indoor)drawIndoor(cg,time);else drawTownWorld(cg,time);town.sceneCache={key,canvas:c};}g.drawImage(town.sceneCache.canvas,0,0);if(!town.indoor)drawTownRoute(g,time);}
function advanceTownMovement(dt){let dx=0,dy=0;const keys=town.keys;if(keys.has('ArrowUp')||keys.has('w'))dy--;if(keys.has('ArrowDown')||keys.has('s'))dy++;if(keys.has('ArrowLeft')||keys.has('a'))dx--;if(keys.has('ArrowRight')||keys.has('d'))dx++;const manual=!!(dx||dy);if(manual){town.path=[];town.autoDoor=null;const length=Math.hypot(dx,dy);dx/=length;dy/=length;}const speed=!town.indoor&&town.driving?ITEMS.find(it=>it.id===state?.life?.equippedCar)?.speed||180:180;let budget=speed*Math.min(dt,1),moved=0;while(budget>.001&&(manual||town.path.length)){let distance;if(!manual){const p=town.path[0],dist=Math.hypot(p.x-town.x,p.y-town.y);if(dist<.1){town.path.shift();continue}dx=(p.x-town.x)/dist;dy=(p.y-town.y)/dist;distance=Math.min(budget,5,dist);}else distance=Math.min(budget,5);const nx=town.x+dx*distance,ny=town.y+dy*distance,oldx=town.x,oldy=town.y;if(isWalkable(nx,town.y))town.x=nx;if(isWalkable(town.x,ny))town.y=ny;const change=Math.hypot(town.x-oldx,town.y-oldy);if(change<.001){if(!manual){town.path=[];town.autoDoor=null;}break;}budget-=distance;moved+=change;town.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');}town.step+=moved*.07;}

function drawTownFrame(time){const g=town.ctx,canvas=town.canvas;if(!g||!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2),w=rect.width,h=rect.height;if(w<1||h<1){requestAnimationFrame(drawTownFrame);return}if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}const dt=Math.min(1,(time-(town.lastTime||time))/1000);town.lastTime=time;if(!town.panel&&!town.transition&&!document.querySelector('dialog[open]')){advanceTownMovement(dt);if(!town.path.length&&town.autoPickup){town.autoPickup=false;if(Math.hypot(town.x-PHONE_SPOT.x,town.y-PHONE_SPOT.y)<75)pickupPhone();}if(!town.path.length&&town.autoDoor){const id=town.autoDoor;town.autoDoor=null;enterBuilding(id)}town.nearest=nearbyTown();const n=town.nearest;const interact=$('interactTown'),disabled=!n,caption=n?'E · '+(n.label||'進入店鋪'):'E · 互動';if(interact.disabled!==disabled)interact.disabled=disabled;if(interact.textContent!==caption)interact.textContent=caption;if(town.path.length)setPrompt((town.autoDoor?'走向 '+BUILDINGS.find(b=>b.id===town.autoDoor).name:'正在走路')+' · 剩餘 '+Math.ceil(town.path.length/3)+' 步');else if(n)setPrompt(n.label||'按 E 進入 '+n.name);else if(!town.path.length)setPrompt(town.indoor?(town.indoor==='home'?'走到右邊床旁，按 E 休息。':'走近櫃檯，與店員聊聊。'):'點店面走近 · WASD／方向鍵移動 · E 進店');if(state&&time-town.lastNeeds>60000){if(town.lastNeeds){state.life.hunger=Math.max(0,state.life.hunger-1);state.life.energy=Math.max(0,state.life.energy-1);persist();renderLifeHud()}town.lastNeeds=time;}}
const world=town.indoor?ROOM:WORLD,scale=town.indoor?Math.min(w/1050,h/760):Math.max(w/1450,h/900),viewW=w/scale,viewH=h/scale;town.cam={x:town.indoor?(ROOM.w-viewW)/2:Math.max(0,Math.min(WORLD.w-viewW,town.x-viewW/2)),y:town.indoor?(ROOM.h-viewH)/2:Math.max(0,Math.min(WORLD.h-viewH,town.y-viewH/2)),scale};g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,w,h);g.scale(scale,scale);g.translate(-town.cam.x,-town.cam.y);townBackground(g,time/1000);drawFoundPhone(g,time/1000);if(!town.indoor&&town.driving){const car=ITEMS.find(it=>it.id===state?.life?.equippedCar);carSprite(g,town.x,town.y-15,car?.color||'#708b76',{right:0,left:Math.PI,up:-Math.PI/2,down:Math.PI/2}[town.dir],.85)}else drawHuman(g,town.x,town.y,'#48695d',town.step,true);townText(g,'你',town.x,town.y-67,11,'#f9f3da');if(town.nearest&&!town.panel){g.strokeStyle='#fdf3cc';g.lineWidth=2;g.beginPath();g.arc(town.x,town.y+2,22+Math.sin(time/250)*2,0,Math.PI*2);g.stroke()}requestAnimationFrame(drawTownFrame)}
function initTown(){const c=$('townCanvas');if(!c?.getContext)return;town.canvas=c;town.ctx=c.getContext('2d');if(!town.ctx)return;for(const b of BUILDINGS){const type=SHOPS[b.id]||['bank','lender'].includes(b.id)?b.id:['cafe','luxury'].includes(b.id)?'temple':b.id==='car'?'night':'bank';const image=new Image();image.onload=()=>{town.portraitVersion=(town.portraitVersion||0)+1;};image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(avatar(type).replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" '));town.portraits[b.id]=image;}updateTownNavigation();renderLifeHud();$('townHome').onclick=()=>{if(town.indoor)exitBuilding();else{closeTownPanel();town.path=routeTown(town.x,town.y,800,575,null);town.autoDoor=null}};$('driveToggle').onclick=()=>{if(!state?.life?.equippedCar)return toast('還沒有自己的車，先走去山海車行看看吧。');if(town.indoor)return toast('車停在店外，先走出店鋪才能駕駛。');town.driving=!town.driving;town.path=[];renderLifeHud();toast(town.driving?'上車了，移動速度提高。':'車停好了，慢慢散步吧。')};$('openAssets').onclick=()=>setPage('assets');$('closeCounter').onclick=closeTownPanel;$('interactTown').onclick=interactTown;$('toggleMap').onclick=()=>{$('townMap').classList.toggle('hidden');updateTownNavigation()};$('closeMap').onclick=()=>$('townMap').classList.add('hidden');$('destinationList').onclick=e=>{const b=e.target.closest('[data-destination]');if(b)walkToBuilding(b.dataset.destination)};
c.addEventListener('pointerdown',e=>{if(town.panel)return closeTownPanel();if(town.transition)return;const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/town.cam.scale+town.cam.x,y=(e.clientY-r.top)/town.cam.scale+town.cam.y;if(!town.indoor){if(state&&!state.timeTravel.phoneFound&&Math.hypot(x-PHONE_SPOT.x,y-PHONE_SPOT.y)<50)return locatePhone();const b=BUILDINGS.find(b=>x>b.x-20&&x<b.x+b.w+20&&y>b.y-50&&y<b.y+b.h+50);if(b)return walkToBuilding(b.id)}else{if(y>175&&y<355&&x>280&&x<720&&town.indoor!=='home'){town.path=routeTown(town.x,town.y,500,365);town.autoDoor=null;c.focus();return}if(town.indoor==='home'&&x>650&&x<885&&y>160&&y<360){town.path=routeTown(town.x,town.y,740,385);c.focus();return}}town.path=routeTown(town.x,town.y,x,y);town.autoDoor=null;c.focus()});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.length===1?e.key.toLowerCase():e.key;if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)){if(!town.panel){e.preventDefault();town.keys.add(key)}}if(key==='e'){e.preventDefault();interactTown()}if(key==='Escape')closeTownPanel()});window.addEventListener('keyup',e=>town.keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>town.keys.clear());document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);town.path=[];town.autoDoor=null;town.keys.add(b.dataset.move)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>town.keys.delete(b.dataset.move))});requestAnimationFrame(drawTownFrame);}

